    // V[n][k] = n*8 + k + 1 ; Kt[k][n] = k*8 + n + 1
    for (int n = 0; n < 16; n++) for (int k = 0; k < 8; k++) hV[n*8+k] = (uint16_t)(n*8 + k + 1);
    for (int k = 0; k < 16; k++) for (int n = 0; n < 8; n++) hKt[k*8+n] = (uint16_t)(k*8 + n + 1);

    uint16_t *dA, *dB, *dV, *dKt;
    int *dErrs;
    CHECK_CU(cudaMalloc(&dA, sizeof(hA))); CHECK_CU(cudaMalloc(&dB, sizeof(hB)));
    CHECK_CU(cudaMalloc(&dV, sizeof(hV))); CHECK_CU(cudaMalloc(&dKt, sizeof(hKt)));
    CHECK_CU(cudaMalloc(&dErrs, sizeof(int)));
    CHECK_CU(cudaMemcpy(dA, hA, sizeof(hA), cudaMemcpyHostToDevice));
    CHECK_CU(cudaMemcpy(dB, hB, sizeof(hB), cudaMemcpyHostToDevice));
    CHECK_CU(cudaMemcpy(dV, hV, sizeof(hV), cudaMemcpyHostToDevice));
    CHECK_CU(cudaMemcpy(dKt, hKt, sizeof(hKt), cudaMemcpyHostToDevice));

    int errs = 0;
    CHECK_CU(cudaMemcpy(dErrs, &errs, sizeof(int), cudaMemcpyHostToDevice));
    probeA<<<1, 32>>>(dA, dB, dErrs, 0);
    CHECK_CU(cudaDeviceSynchronize());
    CHECK_CU(cudaMemcpy(&errs, dErrs, sizeof(int), cudaMemcpyDeviceToHost));
    printf("probeA raw-ldmatrix order: %s\n", errs == 0 ? "PASS" : "FAIL");

    errs = 0;
    CHECK_CU(cudaMemcpy(dErrs, &errs, sizeof(int), cudaMemcpyHostToDevice));
    probeA<<<1, 32>>>(dA, dB, dErrs, 1);
    CHECK_CU(cudaDeviceSynchronize());
    CHECK_CU(cudaMemcpy(&errs, dErrs, sizeof(int), cudaMemcpyDeviceToHost));
    printf("probeA swapped(1<->2):   %s\n", errs == 0 ? "PASS" : "FAIL");

    errs = 0;
    CHECK_CU(cudaMemcpy(dErrs, &errs, sizeof(int), cudaMemcpyHostToDevice));
    probeB<<<1, 32>>>(dV, dA, dErrs);
    CHECK_CU(cudaDeviceSynchronize());
    CHECK_CU(cudaMemcpy(&errs, dErrs, sizeof(int), cudaMemcpyDeviceToHost));
    printf("probeB trans-from-V[n][k]: %s\n", errs == 0 ? "PASS" : "FAIL");

    errs = 0;
    CHECK_CU(cudaMemcpy(dErrs, &errs, sizeof(int), cudaMemcpyHostToDevice));
    probeC<<<1, 32>>>(dKt, dA, dErrs);
    CHECK_CU(cudaDeviceSynchronize());
    CHECK_CU(cudaMemcpy(&errs, dErrs, sizeof(int), cudaMemcpyDeviceToHost));
    printf("probeC trans-from-Kt[k][n]: %s\n", errs == 0 ? "PASS" : "FAIL");
    return 0;
}

