    for (int l = 0; l < 32; l++) {
        uint16_t v[4];
        v[0] = hOut[l*2+0] & 0xffff; v[1] = hOut[l*2+0] >> 16;
        v[2] = hOut[l*2+1] & 0xffff; v[3] = hOut[l*2+1] >> 16;
        printf("lane %2d (c=%d t=%d): r0=(%d,%d) r1=(%d,%d) | expect b0=(B[2c][t],B[2c+1][t]) b1=(B[2c+8][t],B[2c+9][t])\n",
               l, l%4, l/4, (int)v[0], (int)v[1], (int)v[2], (int)v[3]);
    }
    return 0;
}

